"use client"

import { createAuthClient } from "better-auth/react"

export const authClient = createAuthClient({
	baseURL: typeof window !== "undefined" ? window.location.origin : "",
})

export const { signIn, signOut, signUp, useSession, forgetPassword, resetPassword } = authClient

/** Demo mode runs without GitHub or database env — memory adapter + fixed secret. */
export function isAuthDemoMode(): boolean {
	if (process.env["AUTH_DEMO_MODE"] === "false") {
		return false
	}
	const hasGithub =
		Boolean(process.env["GITHUB_CLIENT_ID"]?.trim()) && Boolean(process.env["GITHUB_CLIENT_SECRET"]?.trim())
	const hasDatabase = Boolean(process.env["DATABASE_URL"]?.trim())
	return !hasGithub || !hasDatabase
}

export function getAuthBaseUrl(): string {
	if (process.env["BETTER_AUTH_URL"]) {
		return process.env["BETTER_AUTH_URL"]
	}
	if (process.env["VERCEL_URL"]) {
		return `https://${process.env["VERCEL_URL"]}`
	}
	return process.env["NEXT_PUBLIC_SITE_URL"] ?? "http://localhost:3000"
}

import "server-only"

import { betterAuth } from "better-auth"
import { memoryAdapter } from "better-auth/adapters/memory"
import { nextCookies } from "better-auth/next-js"

import { getAuthBaseUrl, isAuthDemoMode } from "./auth.env"

const demoMode = isAuthDemoMode()

const githubClientId = process.env["GITHUB_CLIENT_ID"]?.trim()
const githubClientSecret = process.env["GITHUB_CLIENT_SECRET"]?.trim()

const socialProviders =
	!demoMode && githubClientId && githubClientSecret
		? {
				github: {
					clientId: githubClientId,
					clientSecret: githubClientSecret,
				},
			}
		: {}

export const auth = betterAuth({
	appName: "Feature Kit",
	secret: process.env["BETTER_AUTH_SECRET"] ?? "feature-kit-demo-auth-secret",
	baseURL: getAuthBaseUrl(),
	database: memoryAdapter({}),
	emailAndPassword: {
		enabled: true,
		autoSignIn: true,
		requireEmailVerification: false,
	},
	...(Object.keys(socialProviders).length > 0 ? { socialProviders } : {}),
	plugins: [nextCookies()],
})

export { demoMode as authDemoMode }

import type { ReactNode } from "react"
import Link from "next/link"

import { Alert, AlertDescription, AlertTitle } from "@/components/ui/alert"
import { Card, CardContent, CardDescription, CardFooter, CardHeader, CardTitle } from "@/components/ui/card"
import { cn } from "@/lib/utils"

export function AuthCardLayout({
	title,
	description,
	children,
	footer,
	className,
}: {
	title: string
	description?: string
	children: ReactNode
	footer?: ReactNode
	className?: string
}) {
	return (
		<Card className={cn("w-full max-w-md border shadow-sm", className)}>
			<CardHeader className="space-y-1">
				<CardTitle className="text-2xl">{title}</CardTitle>
				{description ? <CardDescription>{description}</CardDescription> : null}
			</CardHeader>
			<CardContent className="grid gap-4">{children}</CardContent>
			{footer ? <CardFooter className="flex flex-col gap-4 border-t pt-4">{footer}</CardFooter> : null}
		</Card>
	)
}

export function AuthFooterNote({ hint, action, href }: { hint: string; action: string; href: string }) {
	return (
		<p className="text-center text-muted-foreground text-sm">
			{hint}{" "}
			<Link className="text-primary underline underline-offset-4 hover:text-primary/80" href={href}>
				{action}
			</Link>
		</p>
	)
}

export function AuthDemoCallout() {
	return (
		<Alert>
			<AlertTitle>Demo mode</AlertTitle>
			<AlertDescription>
				Auth uses an in-memory better-auth store. Sessions reset on cold starts. Use any email and password (8+
				characters) to sign in — no environment variables required.
			</AlertDescription>
		</Alert>
	)
}

"use client"

import { FormKit } from "@/lib/feature-kit/form"
import { useTransition } from "react"
import { toast } from "sonner"

import { forgetPassword } from "../core/auth.client"
import { AuthSchema, type ForgotPasswordInput } from "../schema/auth-schema"
import { AuthFooterNote } from "./auth-card-layout"

export function ForgotPasswordForm() {
	const [pending, startTransition] = useTransition()

	return (
		<div className="grid gap-6">
			<FormKit
				schema={AuthSchema.FORGOT_PASSWORD.INPUT}
				defaultValues={{ email: "" }}
				isPending={pending}
				onSubmit={(data: ForgotPasswordInput) => {
					startTransition(async () => {
						const toastId = toast.loading("Sending reset link…")
						const result = await forgetPassword({
							email: data.email,
							redirectTo: "/docs/examples/auth/reset-password",
						})
						if (result?.error) {
							toast.error(result.error.message ?? "Could not send reset email", { id: toastId })
							return
						}
						toast.success("Check your inbox (demo: link logged in network tab)", { id: toastId })
					})
				}}>
				<FormKit.Field name="email" label="Email" type="text" required />
				<FormKit.Actions>
					<FormKit.Submit label="Send reset link" pendingLabel="Sending…" />
				</FormKit.Actions>
			</FormKit>
			<AuthFooterNote action="Back to sign in" hint="Remembered your password?" href="/docs/examples/auth/sign-in" />
		</div>
	)
}

"use client"

import { GitHubIcon } from "./auth.github-icon"
import { useTransition } from "react"
import { toast } from "sonner"

import { Button } from "@/components/ui/button"

import { signIn } from "../core/auth.client"

export function GitHubSignInButton() {
	const [pending, startTransition] = useTransition()

	return (
		<Button
			className="w-full"
			disabled={pending}
			onClick={() => {
				startTransition(async () => {
					const toastId = toast.loading("Connecting to GitHub…")
					const result = await signIn.social({
						provider: "github",
						callbackURL: window.location.pathname,
					})
					if (result?.error) {
						toast.error(result.error.message ?? "GitHub sign-in is unavailable in demo mode.", {
							id: toastId,
							description: "Use email and password, or configure GITHUB_CLIENT_ID in production.",
						})
						return
					}
					toast.success("Redirecting…", { id: toastId })
				})
			}}
			type="button"
			variant="outline">
			<GitHubIcon className="size-4" />
			Continue with GitHub
		</Button>
	)
}

