"use client"

import { FormKit } from "@/lib/feature-kit/form"
import { useRouter } from "next/navigation"
import { useTransition } from "react"
import { toast } from "sonner"

import { resetPassword } from "../core/auth.client"
import { AuthSchema, type ResetPasswordInput } from "../schema/auth-schema"
import { AuthFooterNote } from "./auth-card-layout"

export function ResetPasswordForm({ token }: { token?: string }) {
	const router = useRouter()
	const [pending, startTransition] = useTransition()

	return (
		<div className="grid gap-6">
			<FormKit
				schema={AuthSchema.RESET_PASSWORD.INPUT}
				defaultValues={{ password: "", confirmPassword: "" }}
				isPending={pending}
				onSubmit={(data: ResetPasswordInput) => {
					startTransition(async () => {
						const toastId = toast.loading("Updating password…")
						const result = await resetPassword({
							newPassword: data.password,
							token: token ?? "demo-token",
						})
						if (result?.error) {
							toast.error(result.error.message ?? "Reset failed", { id: toastId })
							return
						}
						toast.success("Password updated", { id: toastId })
						router.push("/docs/examples/auth/sign-in")
					})
				}}>
				<FormKit.Field name="password" label="New password" type="text" inputType="password" required />
				<FormKit.Field
					name="confirmPassword"
					label="Confirm password"
					type="text"
					inputType="password"
					required
				/>
				<FormKit.Actions>
					<FormKit.Submit label="Reset password" pendingLabel="Saving…" />
				</FormKit.Actions>
			</FormKit>
			<AuthFooterNote action="Sign in" hint="Done?" href="/docs/examples/auth/sign-in" />
		</div>
	)
}

"use client"

import { FormKit } from "@/lib/feature-kit/form"
import { useRouter } from "next/navigation"
import { useTransition } from "react"
import { toast } from "sonner"

import { signIn } from "../core/auth.client"
import { AuthSchema, type SignInInput } from "../schema/auth-schema"
import { AuthFooterNote } from "./auth-card-layout"
import { AuthProviders } from "./auth.providers"

export function SignInForm({ redirectTo = "/docs/examples/auth" }: { redirectTo?: string }) {
	const router = useRouter()
	const [pending, startTransition] = useTransition()

	return (
		<div className="grid gap-6">
			<AuthProviders />
			<FormKit
				schema={AuthSchema.SIGN_IN.INPUT}
				defaultValues={{ email: "", password: "", rememberMe: true }}
				isPending={pending}
				onSubmit={(data: SignInInput) => {
					startTransition(async () => {
						const toastId = toast.loading("Signing in…")
						const result = await signIn.email({
							email: data.email,
							password: data.password,
							rememberMe: data.rememberMe ?? true,
						})
						if (result?.error) {
							toast.error(result.error.message ?? "Sign in failed", { id: toastId })
							return
						}
						toast.success("Signed in", { id: toastId })
						router.push(redirectTo)
						router.refresh()
					})
				}}>
				<FormKit.Field name="email" label="Email" type="text" placeholder="you@example.com" required />
				<FormKit.Field name="password" label="Password" type="text" inputType="password" required />
				<FormKit.Field name="rememberMe" label="Remember me" type="switch" />
				<FormKit.Actions>
					<FormKit.Submit label="Sign in" pendingLabel="Signing in…" />
				</FormKit.Actions>
			</FormKit>
			<AuthFooterNote
				action="Create an account"
				hint="New here?"
				href="/docs/examples/auth/sign-up"
			/>
			<AuthFooterNote
				action="Reset password"
				hint="Forgot your password?"
				href="/docs/examples/auth/forgot-password"
			/>
		</div>
	)
}

