"use client"

import { FormKit } from "@/lib/feature-kit/form"
import { useRouter } from "next/navigation"
import { useTransition } from "react"
import { toast } from "sonner"

import { signUp } from "../core/auth.client"
import { AuthSchema, type SignUpInput } from "../schema/auth-schema"
import { AuthFooterNote } from "./auth-card-layout"
import { AuthProviders } from "./auth.providers"

export function SignUpForm({ redirectTo = "/docs/examples/auth" }: { redirectTo?: string }) {
	const router = useRouter()
	const [pending, startTransition] = useTransition()

	return (
		<div className="grid gap-6">
			<AuthProviders />
			<FormKit
				schema={AuthSchema.SIGN_UP.INPUT}
				defaultValues={{ name: "", email: "", password: "" }}
				isPending={pending}
				onSubmit={(data: SignUpInput) => {
					startTransition(async () => {
						const toastId = toast.loading("Creating account…")
						const result = await signUp.email({
							email: data.email,
							password: data.password,
							name: data.name,
						})
						if (result?.error) {
							toast.error(result.error.message ?? "Sign up failed", { id: toastId })
							return
						}
						toast.success("Account created", { id: toastId })
						router.push(redirectTo)
						router.refresh()
					})
				}}>
				<FormKit.Field name="name" label="Name" type="text" required />
				<FormKit.Field name="email" label="Email" type="text" required />
				<FormKit.Field name="password" label="Password" type="text" inputType="password" required />
				<FormKit.Actions>
					<FormKit.Submit label="Sign up" pendingLabel="Creating…" />
				</FormKit.Actions>
			</FormKit>
			<AuthFooterNote action="Sign in" hint="Already have an account?" href="/docs/examples/auth/sign-in" />
		</div>
	)
}

"use client"

import { useRouter, useSearchParams } from "next/navigation"
import { useTransition } from "react"
import { toast } from "sonner"

import { Button } from "@/components/ui/button"

import { signIn } from "../core/auth.client"
import { AuthFooterNote } from "./auth-card-layout"

export function VerifyEmailPanel() {
	const searchParams = useSearchParams()
	const email = searchParams.get("email") ?? "demo@featurekit.dev"
	const router = useRouter()
	const [pending, startTransition] = useTransition()

	return (
		<div className="grid gap-4">
			<p className="text-muted-foreground text-sm">
				Demo mode skips email delivery. Click verify to continue as <strong>{email}</strong>.
			</p>
			<Button
				disabled={pending}
				onClick={() => {
					startTransition(async () => {
						const toastId = toast.loading("Verifying…")
						const result = await signIn.email({
							email,
							password: "DemoPass1",
						})
						if (result?.error) {
							toast.error(result.error.message ?? "Verification failed", { id: toastId })
							return
						}
						toast.success("Email verified", { id: toastId })
						router.push("/docs/examples/auth")
						router.refresh()
					})
				}}
				type="button">
				Mark email verified
			</Button>
			<AuthFooterNote action="Sign in" hint="Already verified?" href="/docs/examples/auth/sign-in" />
		</div>
	)
}

import { z } from "zod"

export const PASSWORD_MIN = 8

export const AuthSchema = {
	SIGN_IN: {
		INPUT: z.object({
			email: z.string().email("Enter a valid email"),
			password: z.string().min(PASSWORD_MIN, "Please enter your password"),
			rememberMe: z.boolean().optional(),
		}),
	},
	SIGN_UP: {
		INPUT: z.object({
			name: z.string().min(2, "Name is too short").trim(),
			email: z.string().email("Enter a valid email").trim(),
			password: z
				.string()
				.min(8, "Password must be at least 8 characters long")
				.regex(/[A-Z]/, "Password must contain at least one uppercase letter")
				.regex(/[a-z]/, "Password must contain at least one lowercase letter")
				.regex(/[0-9]/, "Password must contain at least one number"),
		}),
	},
	FORGOT_PASSWORD: {
		INPUT: z.object({
			email: z.string().email("Enter a valid email").trim(),
		}),
	},
	RESET_PASSWORD: {
		INPUT: z
			.object({
				password: z
					.string()
					.min(8, "Password must be at least 8 characters long")
					.regex(/[A-Z]/, "Password must contain at least one uppercase letter")
					.regex(/[a-z]/, "Password must contain at least one lowercase letter")
					.regex(/[0-9]/, "Password must contain at least one number"),
				confirmPassword: z.string(),
			})
			.refine((data) => data.password === data.confirmPassword, {
				message: "Passwords do not match",
				path: ["confirmPassword"],
			}),
	},
	VERIFY_EMAIL: {
		INPUT: z.object({
			email: z.string().email("Enter a valid email").optional(),
		}),
	},
}

export type SignInInput = z.infer<typeof AuthSchema.SIGN_IN.INPUT>
export type SignUpInput = z.infer<typeof AuthSchema.SIGN_UP.INPUT>
export type ForgotPasswordInput = z.infer<typeof AuthSchema.FORGOT_PASSWORD.INPUT>
export type ResetPasswordInput = z.infer<typeof AuthSchema.RESET_PASSWORD.INPUT>
